#include "phylogeny.h"
Tree tree_create(int size) {
    Tree out = {0};
    out.size = out.next = size;
    return out;
}
int tree_internal(Tree *tree) {
    tree->present[tree->next] = 1;
    return tree->next++;
}
void connect(Tree *tree, int a, int b, double length) {
    tree->present[a] = tree->present[b] = 1;
    tree->adjacent[a][b] = tree->adjacent[b][a] = 1;
    tree->length[a][b] = tree->length[b][a] = length;
}
double disconnect(Tree *tree, int a, int b) {
    double length = tree->length[a][b];
    tree->adjacent[a][b] = tree->adjacent[b][a] = 0;
    return length;
}
static void root_visit(const Tree *tree, Rooted *root, int node, int parent) {
    root->parent[node] = parent;
    root->order[root->count++] = node;
    if (node < tree->size)
        root->masks[node] = 1u << node;
    for (int child = 0; child < tree->next; ++child)
        if (tree->adjacent[node][child] && child != parent) {
            root->children[node][root->child_count[node]++] = child;
            root_visit(tree, root, child, node);
            root->masks[node] |= root->masks[child];
        }
}
Rooted rooted(const Tree *tree, int outgroup) {
    Rooted out = {0};
    out.outgroup = outgroup;
    while (!tree->adjacent[outgroup][out.root])
        ++out.root;
    root_visit(tree, &out, out.root, -1);
    out.ingroup = out.masks[out.root] ^ (1u << outgroup);
    return out;
}
Masks split_set(const Tree *tree, const Rooted *root) {
    Masks out = {0};
    for (int node = tree->size; node < tree->next; ++node)
        if (tree->present[node] && node != root->root)
            out.values[out.count++] = root->masks[node];
    return out;
}
Tree star(int size, const int *taxa, int count) {
    Tree out = tree_create(size);
    int root = tree_internal(&out);
    for (int i = 0; i < count; ++i)
        connect(&out, root, taxa[i], 0);
    return out;
}
Tree neighbor_joining(const Matrix *matrix, int size, const int *taxa, int length) {
    Tree tree = tree_create(size);
    double distances[32][32] = {{0}};
    int active[32], count = length;
    memcpy(active, taxa, (size_t)length * sizeof(int));
    for (int i = 0; i < length; ++i)
        for (int j = 0; j < length; ++j)
            distances[taxa[i]][taxa[j]] = matrix->values[taxa[i]][taxa[j]];
    while (count >= 4) {
        double totals[32] = {0}, best = INFINITY;
        int first = 0, second = 0;
        for (int i = 0; i < count; ++i)
            for (int j = 0; j < count; ++j)
                if (i != j)
                    totals[active[i]] += distances[active[i]][active[j]];
        for (int i = 0; i < count; ++i)
            for (int j = i + 1; j < count; ++j) {
                int a = active[i], b = active[j];
                double value = (count - 2) * distances[a][b] - totals[a] - totals[b];
                if (value < best) {
                    best = value;
                    first = a;
                    second = b;
                }
            }
        int node = tree_internal(&tree);
        double distance = distances[first][second],
               left = distance / 2 + (totals[first] - totals[second]) / (2 * (count - 2));
        connect(&tree, first, node, left);
        connect(&tree, second, node, distance - left);
        int remaining[32], n = 0;
        for (int i = 0; i < count; ++i) {
            int other = active[i];
            if (other != first && other != second) {
                remaining[n++] = other;
                distances[node][other] = distances[other][node] =
                    (distances[first][other] + distances[second][other] - distance) / 2;
            }
        }
        remaining[n++] = node;
        memcpy(active, remaining, (size_t)n * sizeof(int));
        count = n;
    }
    int a = active[0], b = active[1], c = active[2], node = tree_internal(&tree);
    double ab = distances[a][b], ac = distances[a][c], bc = distances[b][c];
    connect(&tree, a, node, (ab + ac - bc) / 2);
    connect(&tree, b, node, (ab + bc - ac) / 2);
    connect(&tree, c, node, (ac + bc - ab) / 2);
    for (int i = 0; i < tree.next; ++i)
        for (int j = i + 1; j < tree.next; ++j)
            if (tree.adjacent[i][j] && tree.length[i][j] < 0) {
                connect(&tree, i, j, 0);
                ++tree.negative;
            }
    return tree;
}
static void path_visit(const Tree *tree, int node, int parent, int unit, double output[32]) {
    for (int child = 0; child < tree->next; ++child)
        if (tree->adjacent[node][child] && child != parent) {
            output[child] = output[node] + (unit ? 1 : tree->length[node][child]);
            path_visit(tree, child, node, unit, output);
        }
}
void paths(const Tree *tree, int start, int unit, double output[32]) {
    memset(output, 0, 32 * sizeof(double));
    path_visit(tree, start, -1, unit, output);
}
Matrix patristic(const Tree *tree) {
    Matrix out = {0};
    for (int a = 0; a < tree->size; ++a)
        if (tree->present[a]) {
            double distances[32];
            paths(tree, a, 0, distances);
            for (int b = 0; b < tree->size; ++b)
                if (tree->present[b])
                    out.values[a][b] = distances[b];
        }
    return out;
}

#include "phylogeny.h"
static char *formatted(const char *pattern, va_list args) {
    va_list copy;
    va_copy(copy, args);
    int n = vsnprintf(NULL, 0, pattern, copy);
    va_end(copy);
    char *out = malloc((size_t)n + 1);
    vsnprintf(out, (size_t)n + 1, pattern, args);
    return out;
}
char *format(const char *pattern, ...) {
    va_list args;
    va_start(args, pattern);
    char *out = formatted(pattern, args);
    va_end(args);
    return out;
}
void text(Text *out, const char *pattern, ...) {
    va_list args;
    va_start(args, pattern);
    char *part = formatted(pattern, args);
    va_end(args);
    size_t count = strlen(part);
    if (out->length + count + 1 > out->capacity) {
        out->capacity = 2 * (out->length + count + 1);
        out->data = realloc(out->data, out->capacity);
    }
    memcpy(out->data + out->length, part, count + 1);
    out->length += count;
    free(part);
}
void line(Lines *out, const char *pattern, ...) {
    if (out->count == out->capacity) {
        out->capacity = out->capacity ? out->capacity * 2 : 32;
        out->values = realloc(out->values, (size_t)out->capacity * sizeof(char *));
    }
    va_list args;
    va_start(args, pattern);
    out->values[out->count++] = formatted(pattern, args);
    va_end(args);
}
char *read_line(FILE *input) {
    Text out = {0};
    int c;
    while ((c = fgetc(input)) != EOF && c != '\n')
        text(&out, "%c", c);
    if (c == EOF && out.length == 0) {
        free(out.data);
        return NULL;
    }
    if (!out.data)
        text(&out, "");
    return out.data;
}
char *real(double value, int digits) {
    char *out = format("%.*f", digits, value);
    if (out[0] == '-') {
        int zero = 1;
        for (int i = 1; out[i]; ++i)
            if (out[i] != '0' && out[i] != '.')
                zero = 0;
        if (zero)
            memmove(out, out + 1, strlen(out));
    }
    return out;
}
char *symbols(Mask mask, int size) {
    char *out = malloc((size_t)size + 1);
    for (int t = 0; t < size; ++t)
        out[t] = mask & (1u << t) ? '*' : '.';
    out[size] = 0;
    return out;
}
static Rooted ordered_root(const Tree *tree, char names[16][21], int outgroup) {
    Rooted root = rooted(tree, outgroup);
    const char *minimum[32] = {0};
    for (int i = root.count - 1; i >= 0; --i) {
        int node = root.order[i];
        if (node < tree->size)
            minimum[node] = names[node];
        else {
            for (int j = 1; j < root.child_count[node]; ++j) {
                int child = root.children[node][j], k = j;
                while (k > 0 && strcmp(minimum[root.children[node][k - 1]], minimum[child]) > 0) {
                    root.children[node][k] = root.children[node][k - 1];
                    --k;
                }
                root.children[node][k] = child;
            }
            minimum[node] = minimum[root.children[node][0]];
        }
    }
    return root;
}
static void render(Text *out, const Tree *tree, const Rooted *root, char names[16][21], int node,
                   int lengths, const int *support) {
    if (node < tree->size)
        text(out, "%s", names[node]);
    else {
        text(out, "(");
        for (int i = 0; i < root->child_count[node]; ++i) {
            if (i)
                text(out, ",");
            render(out, tree, root, names, root->children[node][i], lengths, support);
        }
        text(out, ")");
        if (support && node != root->root)
            text(out, "%d", support[root->masks[node]]);
    }
    if (lengths && node != root->root)
        text(out, ":%s", real(tree->length[node][root->parent[node]], 5));
}
char *newick(const Tree *tree, char names[16][21], int outgroup, int lengths, const int *support) {
    Rooted root = ordered_root(tree, names, outgroup);
    Text out = {0};
    render(&out, tree, &root, names, root.root, lengths, support);
    text(&out, ";");
    return out.data;
}
static void draw(Lines *out, const Tree *tree, const Rooted *root, char names[16][21],
                 const int *support, int node, const char *prefix) {
    for (int i = 0; i < root->child_count[node]; ++i) {
        int child = root->children[node][i], last = i + 1 == root->child_count[node];
        char *label =
            child < tree->size ? names[child] : format("[%d]", support[root->masks[child]]);
        line(out, "%s%s%s", prefix, last ? "`-- " : "|-- ", label);
        char *next = format("%s%s", prefix, last ? "    " : "|   ");
        draw(out, tree, root, names, support, child, next);
        free(next);
    }
}
Lines cladogram(const Tree *tree, char names[16][21], int outgroup, const int *support) {
    Rooted root = ordered_root(tree, names, outgroup);
    Lines out = {0};
    line(&out, "*");
    draw(&out, tree, &root, names, support, root.root, "");
    return out;
}
void save(const char *name, const Lines *lines) {
    char *path = format("output/%s", name);
    FILE *out = fopen(path, "w");
    for (int i = 0; i < lines->count; ++i)
        fprintf(out, "%s\n", lines->values[i]);
    fclose(out);
    free(path);
}
